<?php
require __DIR__.'/db.php';
$count=(int)$pdo->query('SELECT COUNT(*) FROM admins')->fetchColumn();
$message='';
if($_SERVER['REQUEST_METHOD']==='POST' && $count===0){csrf_check();$u=trim($_POST['username']??'');$p=$_POST['password']??'';if(strlen($u)<3||strlen($p)<12)$message='Usuario mínimo 3 caracteres y contraseña mínimo 12.';else{$st=$pdo->prepare('INSERT INTO admins(username,password_hash) VALUES(?,?)');$st->execute([$u,password_hash($p,PASSWORD_DEFAULT)]);header('Location: admin/login.php?created=1');exit;}}
